def select(texto):
    """Referencias que de verdad se citan en ``texto`` (el texto de las celdas Markdown del capítulo)."""
    citadas = [ALL_REFERENCES[k] for k, forma in FORMS.items() if forma in texto]
    sin_usar = [k for k, forma in FORMS.items() if forma not in texto]
    sin_forma = [k for k in ALL_REFERENCES if k not in FORMS]
    return citadas, sin_usar, sin_forma


